	ops = append(ops, diffStringField(base, []string{"ipv6", "address", "interface-identifier"}, prev.IPv6AddressInterfaceIdentifier, cur.IPv6AddressInterfaceIdentifier)...)

	ops = append(ops, diffStringField(base, []string{"mirror", "ingress"}, prev.MirrorIngress, cur.MirrorIngress)...)

