	ops = append(ops, diffBoolField(base, []string{"parameters", "external"}, prev.ParametersExternal, cur.ParametersExternal)...)

	ops = append(ops, diffBoolField(base, []string{"parameters", "nolearning"}, prev.ParametersNolearning, cur.ParametersNolearning)...)

	ops = append(ops, diffBoolField(base, []string{"parameters", "neighbor-suppress"}, prev.ParametersNeighborSuppress, cur.ParametersNeighborSuppress)...)

	ops = append(ops, diffBoolField(base, []string{"parameters", "vni-filter"}, prev.ParametersVNIFilter, cur.ParametersVNIFilter)...)

